q.write_text('\n'.join('\t'.join(r) for r in queries)+'\n'+'\n'.join(helpers)+'\n')
refs={}
for va_s,name,_,end_s in queries:
 va,end=int(va_s,16),int(end_s,16)
 for off in range(raw(va),raw(end),4):
  ins=struct.unpack_from('<I',native,off)[0]
  if ins>>26 in (0x25,5):
   imm=ins&0x3ffffff
   if imm&0x2000000:imm-=0x4000000
   target=va+off-raw(va)+imm*4
   candidates=[r for r in allrows if int(r['preferred_va'],16)==target]
   if len(candidates)==1:
    r=candidates[0];refs[target]=re.sub('[^A-Za-z0-9_]','_',r['type']+'_'+r['method']+'_'+r['token'])
(ROOT/'reports'/('native-'+scope+'-references.tsv')).write_text(('\n'.join(hex(va)+'\t'+name for va,name in sorted(refs.items()))+'\n') if refs else '')
print(scope,len(queries),'methods',len(refs),'managed call aliases')
